/* Browser-local spreadsheet utilities. No file is sent to a server. */
const sheetIO=(()=>{
const utf8=new TextEncoder();
const decode=b=>new TextDecoder('utf-8').decode(b);
function csvRows(text){const first=text.replace(/^\uFEFF/,'');const sample=first.split(/\r?\n/,1)[0]||'';const sep=['\t',',',';'].sort((a,b)=>sample.split(b).length-sample.split(a).length)[0];const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<first.length;i++){const ch=first[i];if(quoted){if(ch==='"'&&first[i+1]==='"'){cell+='"';i++}else if(ch==='"')quoted=false;else cell+=ch}else if(ch==='"')quoted=true;else if(ch===sep){row.push(cell);cell=''}else if(ch==='\n'||ch==='\r'){if(ch==='\r'&&first[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell=''}else cell+=ch}if(quoted)throw Error('CSV 引号未闭合');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
function crc32(bytes){let n=0xffffffff;for(const b of bytes){n^=b;for(let i=0;i<8;i++)n=(n>>>1)^((n&1)?0xedb88320:0)}return(n^0xffffffff)>>>0}
function packZip(files){const parts=[],central=[];let offset=0;for(const [name,data] of files){const nameBytes=utf8.encode(name),bytes=typeof data==='string'?utf8.encode(data):data,crc=crc32(bytes);const local=new Uint8Array(30+nameBytes.length),dv=new DataView(local.buffer);dv.setUint32(0,0x04034b50,true);dv.setUint16(4,20,true);dv.setUint16(6,0x0800,true);dv.setUint16(8,0,true);dv.setUint32(14,crc,true);dv.setUint32(18,bytes.length,true);dv.setUint32(22,bytes.length,true);dv.setUint16(26,nameBytes.length,true);local.set(nameBytes,30);parts.push(local,bytes);const dir=new Uint8Array(46+nameBytes.length),cv=new DataView(dir.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x0800,true);cv.setUint16(10,0,true);cv.setUint32(16,crc,true);cv.setUint32(20,bytes.length,true);cv.setUint32(24,bytes.length,true);cv.setUint16(28,nameBytes.length,true);cv.setUint32(42,offset,true);dir.set(nameBytes,46);central.push(dir);offset+=local.length+bytes.length}const centralStart=offset;for(const b of central){parts.push(b);offset+=b.length}const end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,offset-centralStart,true);ev.setUint32(16,centralStart,true);parts.push(end);return new Blob(parts,{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}
async function unpackZip(file){const buf=await file.arrayBuffer(),v=new DataView(buf),b=new Uint8Array(buf);let end=-1;for(let i=b.length-22;i>=Math.max(0,b.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('不是有效的 .xlsx 文件');const entries=new Map(),count=v.getUint16(end+10,true);let pos=v.getUint32(end+16,true);for(let i=0;i<count;i++){if(v.getUint32(pos,true)!==0x02014b50)throw Error('Excel 文件目录损坏');const method=v.getUint16(pos+10,true),size=v.getUint32(pos+20,true),nameLen=v.getUint16(pos+28,true),extra=v.getUint16(pos+30,true),comment=v.getUint16(pos+32,true),local=v.getUint32(pos+42,true),name=decode(b.subarray(pos+46,pos+46+nameLen));if(v.getUint32(local,true)!==0x04034b50)throw Error('Excel 文件内容损坏');const start=local+30+v.getUint16(local+26,true)+v.getUint16(local+28,true);entries.set(name,{method,bytes:b.slice(start,start+size)});pos+=46+nameLen+extra+comment}async function read(name){const ent=entries.get(name);if(!ent)return null;if(ent.method===0)return decode(ent.bytes);if(ent.method!==8)throw Error('Excel 压缩格式暂不支持');if(typeof pako!=='undefined')return decode(pako.inflateRaw(ent.bytes));if(!('DecompressionStream'in window))throw Error('当前浏览器无法读取压缩的 Excel 文件，请另存为 CSV 再上传');let stream;try{stream=new Blob([ent.bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'))}catch{throw Error('当前浏览器无法读取压缩的 Excel 文件，请另存为 CSV 再上传')}return decode(new Uint8Array(await new Response(stream).arrayBuffer()))}return{read,names:[...entries.keys()]}}
function parseXml(text){const doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw Error('Excel 工作表内容无法读取');return doc}
function xlsxRows(xml,shared){const doc=parseXml(xml),rows=[];for(const row of doc.getElementsByTagNameNS('*','row')){const cells=[];for(const c of row.getElementsByTagNameNS('*','c')){const ref=c.getAttribute('r')||'',letters=(ref.match(/[A-Z]+/)||[])[0];let col=letters?0:cells.length;if(letters)for(const ch of letters)col=col*26+ch.charCodeAt(0)-64;col=letters?col-1:col;const type=c.getAttribute('t');let value='';if(type==='inlineStr'){value=[...c.getElementsByTagNameNS('*','t')].map(n=>n.textContent).join('')}else{const v=c.getElementsByTagNameNS('*','v')[0]?.textContent||'';value=type==='s'?shared[Number(v)]||'':v}cells[col]=value}rows.push(cells)}return rows}
async function readRows(file){if(file.size>5*1024*1024)throw Error('文件不能超过 5 MB');const suffix=file.name.toLowerCase().split('.').pop();if(suffix==='csv'||suffix==='tsv'){const bytes=new Uint8Array(await file.arrayBuffer());let text=decode(bytes);if(text.includes('\uFFFD')){try{text=new TextDecoder('gb18030').decode(bytes)}catch{}}return csvRows(text)}if(suffix!=='xlsx')throw Error('请上传 .xlsx、.csv 或 .tsv 文件');const zip=await unpackZip(file),sharedXml=await zip.read('xl/sharedStrings.xml');let shared=[];if(sharedXml){const doc=parseXml(sharedXml);shared=[...doc.getElementsByTagNameNS('*','si')].map(si=>[...si.getElementsByTagNameNS('*','t')].map(t=>t.textContent).join(''))}const path=zip.names.filter(n=>/^xl\/worksheets\/sheet\d+\.xml$/.test(n)).sort((a,b)=>Number(a.match(/\d+/g).at(-1))-Number(b.match(/\d+/g).at(-1)))[0];if(!path)throw Error('Excel 文件中没有工作表');return xlsxRows(await zip.read(path),shared)}
function xmlEscape(s){return String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&quot;'}[ch]))}
function colName(i){let n=i+1,s='';while(n){n--;s=String.fromCharCode(65+n%26)+s;n=Math.floor(n/26)}return s}
function sheetXml(rows){const maxCols=Math.max(...rows.map(r=>r.length));const widths=`<cols>${Array.from({length:maxCols},(_,i)=>{const size=Math.max(...rows.map(r=>Array.from(String(r[i]??'')).reduce((n,ch)=>n+(/[\u4e00-\u9fff]/.test(ch)?2:1),0)));return `<col min=\"${i+1}\" max=\"${i+1}\" width=\"${Math.min(36,Math.max(12,size+3))}\" customWidth=\"1\"/>`}).join('')}</cols>`;return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>${widths}<sheetData>${rows.map((row,ri)=>`<row r="${ri+1}">${row.map((val,ci)=>{const ref=colName(ci)+(ri+1),num=typeof val==='number'&&Number.isFinite(val);return num?`<c r="${ref}" s="${ri===0?1:0}"><v>${val}</v></c>`:`<c r="${ref}" t="inlineStr" s="${ri===0?1:0}"><is><t xml:space="preserve">${xmlEscape(val)}</t></is></c>`}).join('')}</row>`).join('')}</sheetData></worksheet>`}
function workbook(sheets){const n=sheets.length,names=sheets.map(([name])=>name);const types=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>${names.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')}</Types>`;const rels=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`;const book=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${names.map((name,i)=>`<sheet name="${xmlEscape(name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')}</sheets></workbook>`;const bookRels=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${names.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')}<Relationship Id="rId${n+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`;const styles=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Aptos"/></font><font><b/><sz val="11"/><color rgb="FF285D99"/><name val="Aptos"/></font></fonts><fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFEAF3FF"/><bgColor indexed="64"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs><cellXfs count="2"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="1" borderId="0" xfId="0" applyFont="1" applyFill="1"/></cellXfs><cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles></styleSheet>`;return packZip([['[Content_Types].xml',types],['_rels/.rels',rels],['xl/workbook.xml',book],['xl/_rels/workbook.xml.rels',bookRels],['xl/styles.xml',styles],...sheets.map(([,rows],i)=>[`xl/worksheets/sheet${i+1}.xml`,sheetXml(rows)])])}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
return{readRows,workbook,download};
})();
